import request from '@/utils/request'
export function getCfgInfo() {
  return request({
    url: '/jingShiDeng/getCfgInfo',
    method: 'get'
  })
}
export function restart() {
  return request({
    url: '/jingShiDeng/restart',
    method: 'get'
  })
}
export function setCfgInfo(params) {
  return request({
    url: '/jingShiDeng/setCfgInfo',
    method: 'post',
    data: params
  })
}