<script>
import { getCfgInfo } from '@/api/jingShiDeng'
import { Broadcast, BroadcastNot } from '@/api/jingShiDengDB'
import CryptoJS from 'crypto-js';
export default {
  name: 'jingShiDengDB',
  data() {
    return {
      activeName: '1',
      // jingShiDengIP: 'http://127.0.0.1',
      ruleForm: {
        Content: '雨',
        ControllerIpPort: "",
        Flicker: [1, 1],
        FontColor: 1,
        Luminance: 30,
        PathTracking: 1,
        Version: 2
      },
      checkList: [],
      controls: [],
      multitextForm: {
        ControllerIpPort: "",
        Lights: '雨天路滑'
      },
      lightId: '1-4',
      lightIdsLength: 4
    };
  },
  methods: {
    getCfgFun() {
      getCfgInfo().then((res) => {
        const mode = "ECB";               //mode ECB CBC CFB OFB CTR
        const pad = "Pkcs7";              //padding Pkcs7 Iso10126 NoPadding ZeroPadding
        const key = "Utis00000000LsCb";       //key AES-16/24/32byte DES-8byte 3DES-8/16/24byte
        const keyType = "Utf8";           //Utf8 Base64 Hex
        const iv = "";         //iv AES-16byte DES-8byte 3DES-8byte
        const ivType = "Utf8";            //Utf8 Base64 Hex
        const isBase64 = false;           //待解密数据编码 true: Base64, false: Hex
          
        const crypto_key = CryptoJS.enc[keyType].parse(key);
          
        let cfg = {};
        (mode !== "ECB") && (cfg.iv = CryptoJS.enc[ivType].parse(iv));
        cfg.mode = CryptoJS.mode[mode];
        cfg.padding = CryptoJS.pad[pad];

        const cryptoData = isBase64 ? res : CryptoJS.enc.Base64.stringify(CryptoJS.enc.Hex.parse(res));
        const decrypt = CryptoJS.AES.decrypt(cryptoData, crypto_key, cfg)
        const result = JSON.parse(CryptoJS.enc.Utf8.stringify(decrypt));

        this.controls = result.controllers
        this.ruleForm.ControllerIpPort = this.controls[0] ? this.controls[0].ip + ':' + this.controls[0].port : ''
        this.multitextForm.ControllerIpPort = this.ruleForm.ControllerIpPort
      })
    },
    submitForm() {
      if (this.checkList.length > 0) {
        let params = {
          ControllerIpPort: this.ruleForm.ControllerIpPort,
          Version: this.ruleForm.Version
        }
        this.checkList.forEach((item) => {
          if (item == 'Flicker') {
            let arr = []
            this.ruleForm[item].forEach(item => {
              arr.push(item * 1000)
            })
            params[item] = arr
          } else {
            params[item] = this.ruleForm[item]
          }
        })
        Broadcast(params).then(res => {
          if (res.code == 200) {
            this.$message({
              message: res.msg,
              type: 'success'
            });
          }
        })
      } else {
        this.$alert('请勾选需要修改的选项')
      }
    },
    textLengthFun() {
      if (this.lightId){
        let arr = this.lightId.split(';')
        let lightIds = []
        arr.forEach(item => {
          lightIds.push(...this.expandRanges(item))
        })
        this.lightIdsLength = lightIds.filter(Boolean).length
      } else {
        this.lightIdsLength = 0
      }
    },
    expandRanges(rangeStr) {
      return rangeStr.split(',')
        .flatMap(range => {
          const [start, end = start] = range.split('-').map(Number);
          return Array.from({ length: end - start + 1 }, (_, i) => start + i);
        });
    },
    submitMultitext() {
      if (this.lightId) {
        let arr = this.lightId.split(';')
        let lightIds = []
        arr.forEach(item => {
          lightIds.push(...this.expandRanges(item))
        })
        lightIds = lightIds.filter(Boolean)
        let strs = this.multitextForm.Lights.split('')
        if (lightIds.length == strs.length) {
          let params = { Lights: [], ControllerIpPort: this.multitextForm.ControllerIpPort }
          strs.forEach((item, index) => {
            params.Lights.push({ Content: item, LightId: lightIds[index] })
          })
          BroadcastNot(params).then(res => {
            if (res.code == 200) {
              this.$message({
                message: res.msg,
                type: 'success'
              });
            }
          })
        } else {
          this.$alert('文字数量与id数量不符')
        }
      } else {
        this.$alert('雾灯编号不能为空 数值为1-254')
      }
    },
  },
  mounted() {
    // this.jingShiDengIP = this.jingShiDengIP + ':' + window.location.port
    this.getCfgFun()
  }
}
</script>
