import request from '@/utils/request'
export function getCfgInfo() {
  return request({
    url: '/anQuanZhuang/getCfgInfo',
    method: 'get'
  })
}
export function restart() {
  return request({
    url: '/anQuanZhuang/restart',
    method: 'get'
  })
}
export function updateCfgInfo(params) {
  return request({
    url: '/anQuanZhuang/updateCfgInfo',
    method: 'post',
    data: params
  })
}